mapper.select:
SELECT  FROM TC_BANK_CONNECT_LOG


        AND REQUEST_ID LIKE CONCAT('%', #{params.requestId}, '%')


        AND INTERFACE_TYPE = #{params.interfaceType}


        AND IS_SUCCESSFUL = #{params.isSuccessful}


        AND BANK_NAME LIKE CONCAT('%', #{params.bankName}, '%')


        AND OPERATION_TYPE = #{params.operationType}


        AND CONNECTION_CONFIG_ID = #{params.connectionConfigId}


        AND REQUEST_TIME >= #{params.startTime}


        AND REQUEST_TIME <= #{params.endTime}


ORDER BY CREATE_TIME DESC
